from typing import Any, Optional

class Tag:
    """A case-insensitive string tag, hashable and comparable.

    Examples:
        >>> Tag("Python") == Tag("python")
        True
        >>> {Tag("A"), Tag("a"), Tag("B")}
        {Tag('a'), Tag('B')}
    """
    _value: str
    _canonical: str

    def __init__(self, value: str) -> None:
        if value is None:
            raise TypeError("value must be a string")
        self._value = value
        self._canonical = value.lower()

    def __eq__(self, other: Any) -> bool:
        if not isinstance(other, Tag):
            return NotImplemented
        return self._canonical == other._canonical

    def __hash__(self) -> int:
        return hash(self._canonical)

    def __repr__(self) -> str:
        return f"Tag({self._value!r})"

from typing import Any, Dict, List

def deep_copy(obj: Any) -> Any:
    """Return a recursive deep copy of an arbitrary nested object.

    Args:
        obj: The value to deep-copy. May be a dict, list, tuple, or scalar.

    Returns:
        A new value with no shared references to the original.

    Examples:
        >>> a = {"x": [1, {"y": 2}]}
        >>> b = deep_copy(a)
        >>> b["x"][1]["y"] = 99
        >>> a["x"][1]["y"]
        2
    """
    # Bug was: used a default list `seen=[]` which doesn't survive between recursion levels.
    if isinstance(obj, dict):
        return {k: deep_copy(v) for k, v in obj.items()}
    if isinstance(obj, list):
        return [deep_copy(x) for x in obj]
    if isinstance(obj, tuple):
        return tuple(deep_copy(x) for x in obj)
    if isinstance(obj, (set, frozenset)):
        return type(obj)(deep_copy(x) for x in obj)
    return obj

from typing import List, Optional

class Song:
    """A track identified by title and artist."""
    def __init__(self, title: str, artist: str) -> None:
        if not title or artist is None:
            raise ValueError("title and artist must be provided")
        self.title: str = title
        self.artist: str = artist

    def __repr__(self) -> str:
        return f"Song({self.title!r}, {self.artist!r})"

class Playlist:
    """A list of songs whose length is the song count.

    Examples:
        >>> p = Playlist([Song("A", "X"), Song("B", "Y")])
        >>> len(p)
        2
        >>> p[0]
        Song('A', 'X')
    """
    def __init__(self, songs: Optional[List[Song]] = None) -> None:
        self.songs: List[Song] = list(songs) if songs else []

    def __len__(self) -> int:
        return len(self.songs)

    def __getitem__(self, index: int) -> Song:
        return self.songs[index]

