from typing import Union, List

def delete_empty_dirs(root: Union[str, Path]) -> int:
    """Recursively delete empty directories under 'root'.

    Args:
        root: Root directory to scan.

    Returns:
        Number of empty directories removed.

    Examples:
        >>> delete_empty_dirs("/tmp/empty_demo_dir") >= 0
        True
    """
    base = Path(root)
    if not base.is_dir():
        return 0
    removed: List[Path] = []
    for p in sorted(base.rglob("*"), reverse=True):
        if p.is_dir():
            try:
                next(p.iterdir())
            except StopIteration:
                try:
                    p.rmdir()
                    removed.append(p)
                except OSError:
                    pass
            except OSError:
                continue
    try:
        next(base.iterdir())
    except StopIteration:
        try:
            base.rmdir()
            removed.append(base)
        except OSError:
            pass
    except OSError:
        pass
    return len(removed)

