from typing import Optional, List, Any

class BSTNode:
    """A node for a Binary Search Tree."""
    def __init__(self, value: Any) -> None:
        self.value = value
        self.left: Optional['BSTNode'] = None
        self.right: Optional['BSTNode'] = None

class BinarySearchTree:
    """A binary search tree for comparable keys.

    Examples:
        >>> bst = BinarySearchTree()
        >>> for v in [5, 3, 7, 1, 4]: bst.insert(v)
        >>> bst.search(4)
        True
        >>> bst.search(99)
        False
    """
    def __init__(self) -> None:
        self.root: Optional[BSTNode] = None

    def insert(self, value: Any) -> None:
        if self.root is None:
            self.root = BSTNode(value)
            return
        cur = self.root
        while True:
            if value < cur.value:
                if cur.left is None:
                    cur.left = BSTNode(value)
                    return
                cur = cur.left
            elif value > cur.value:
                if cur.right is None:
                    cur.right = BSTNode(value)
                    return
                cur = cur.right
            else:
                return

    def search(self, value: Any) -> bool:
        cur = self.root
        while cur is not None:
            if value == cur.value:
                return True
            if value < cur.value:
                cur = cur.left
            else:
                cur = cur.right
        return False

    def inorder(self) -> List[Any]:
        """Return values via inorder traversal.

        Examples:
            >>> bst = BinarySearchTree()
            >>> for v in [3, 1, 2]: bst.insert(v)
            >>> bst.inorder()
            [1, 2, 3]
        """
        out: List[Any] = []
        self._inorder(self.root, out)
        return out

    def _inorder(self, node: Optional[BSTNode], out: List[Any]) -> None:
        if node is None:
            return
        self._inorder(node.left, out)
        out.append(node.value)
        self._inorder(node.right, out)

if __name__ == "__main__":
    bst = BinarySearchTree()
    for v in [10, 5, 15, 3, 7, 12, 20]:
        bst.insert(v)
    print(bst.inorder())
    print(bst.search(7), bst.search(99))

